"""Fresh-process balanced comparison; unchanged strict native pair; full responses checked."""
from pathlib import Path
import argparse,hashlib,importlib.util,json,os,subprocess,sys,time
R=Path(__file__).resolve().parents[2];N=Path(__file__).resolve().parent
sys.path.insert(0,str(R))
def load(name,path):
 spec=importlib.util.spec_from_file_location(name,path);m=importlib.util.module_from_spec(spec);sys.modules[name]=m;spec.loader.exec_module(m);return m
def run(role,out):
 import tofu_db
 tofu_db.embedded=load('tofu_db.embedded',N/f'{role}-embedded.py')
 perf=load('response_perf',R/'scripts/tofudb_perf_compare.py')
 engine=perf.TofuDbEngine(N/'pinned-build/tofu-db',client_mode='embedded',authority_dir_parent=Path('/tmp'))
 engine.start();rows={}
 try:
  for name,size,count in [('point',17,20000),('64k',65536,1000),('1m',1048576,120),('2m',2097152,60)]:
   payload={'namespace':'response-view','key':name}
   value={'text':('汉字\\\"\n' if name!='point' else '')+'x'*size,'array':[1,2,3,None,True,1.25]}
   engine.execute('record.put',dict(payload,value=value),True)
   reference=engine.execute('record.get',payload,False);assert reference['value']==value and reference['version']==1
   samples=[];cpu=time.process_time();began=time.perf_counter_ns()
   for _ in range(count):
    start=time.perf_counter_ns();result=engine.execute('record.get',payload,False)
    samples.append((time.perf_counter_ns()-start)/1e6);assert result==reference
   rows[name]={'latency':perf._latency_summary(samples),'precise_latency':{'mean_ms':sum(samples)/len(samples),'p50_ms':perf._percentile(sorted(samples),0.50),'p99_ms':perf._percentile(sorted(samples),0.99)},'cpu_seconds':time.process_time()-cpu,'elapsed_seconds':(time.perf_counter_ns()-began)/1e9,'exact_checks':count,'value_sha256':hashlib.sha256(json.dumps(value,ensure_ascii=False).encode()).hexdigest()}
  meta=perf._measurement_metadata({'tofudb':engine})
 finally:engine.stop()
 out.write_text(json.dumps({'role':role,'rows':rows,'metadata':meta,'authority_closed':True},indent=2)+'\n')
def control():
 records=[];order=['baseline','candidate','candidate','baseline','candidate','baseline','baseline','candidate']
 for i,role in enumerate(order,1):
  out=N/f'leg-{i}-{role}.json'
  with (N/f'leg-{i}-{role}.log').open('w') as log:subprocess.run([sys.executable,__file__,'--role',role,'--out',str(out)],env=dict(os.environ,TOFU_DB_REQUEST_PROFILE_EVERY='0'),stdout=log,stderr=subprocess.STDOUT,check=True)
  records.append(json.loads(out.read_text()));print('leg',i,role,'complete',flush=True)
 comparisons={}
 for shape in records[0]['rows']:
  assert len({r['rows'][shape]['value_sha256'] for r in records})==1
  rows={}
  for metric in ['mean_ms','p50_ms','p99_ms','cpu_seconds']:
   values={role:[r['rows'][shape]['cpu_seconds'] if metric=='cpu_seconds' else r['rows'][shape]['precise_latency'][metric] for r in records if r['role']==role] for role in ['baseline','candidate']}
   means={k:sum(v)/len(v) for k,v in values.items()};rows[metric]={'values':values,'means':means,'candidate_reduction_percent':100*(1-means['candidate']/means['baseline'])}
  comparisons[shape]=rows
 (N/'comparison.json').write_text(json.dumps({'order':order,'exact_checks':sum(v['exact_checks'] for r in records for v in r['rows'].values()),'metrics':comparisons,'scope':'same native strict pair; full-response checks; fresh process and authority per leg; shared host; no profiling; 2m P99 uses 60 samples only'},indent=2)+'\n')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--role');p.add_argument('--out',type=Path);a=p.parse_args();run(a.role,a.out) if a.role else control()

