"""Python-only peak traced allocations; not RSS or end-to-end timing."""
from pathlib import Path
import gc,importlib.util,json,sys,tracemalloc
N=Path(__file__).resolve().parent
rows=[]
for role in ['baseline','candidate']:
 spec=importlib.util.spec_from_file_location('memory_embedded',N/f'{role}-embedded.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
 for accelerated in [True,False]:
  if not accelerated:m._fast_json=None
  for size in [64,65536,1048576,2097152]:
   expected={'status':0,'payload':{'text':'汉字\\\"\n'+'x'*size,'nested':[1,False,None,1.25]}}
   encoded=json.dumps(expected,ensure_ascii=False).encode();out=m._ffi.new('uint8_t[]',encoded)
   def decode():
    view=m._ffi.buffer(out,len(encoded))
    return m._loads(memoryview(view) if role=='candidate' else bytes(view))
   assert decode()==expected;peaks=[]
   for _ in range(5):
    gc.collect();tracemalloc.start();actual=decode();current,peak=tracemalloc.get_traced_memory();tracemalloc.stop();assert actual==expected;del actual;peaks.append(peak)
   rows.append({'role':role,'accelerated':accelerated,'payload_characters':size,'encoded_bytes':len(encoded),'peak_traced_bytes':peaks})
(N/'memory.json').write_text(json.dumps({'scope':'Python traced allocations only; buffers/input prepared before tracing; five separate traces; not RSS/allocator/native-memory proof','rows':rows,'exact_checks':96},indent=2)+'\n')
print([(r['role'],r['accelerated'],r['payload_characters'],min(r['peak_traced_bytes'])) for r in rows if r['payload_characters']==2097152])
